-- ============================================================================
-- EC6: Field Development Planning joins the catalog, the SIXTH and LAST
-- Economics course.
--
-- Catalog row (module 'economics'; path_order 58; prereq_slug NULL) plus the
-- three capstones and their eighteen graded fields, generated by
-- /root/ec-wip-fdp/gen_course.py from fields.json and the capstone constants
-- in ec6_fields_capstone.mjs. Deep seeds are three separate migrations; the
-- go-live is a fifth and is HELD until a NextGen production upload carries
-- the route /dashboard/apps/fdp.
--
-- THE ONE SENTENCE THE COURSE IS. A field development plan is a set of
-- numbers that must agree with each other, and the discipline of planning is
-- knowing which number each answer came from, what it was measured against,
-- and when the honest answer is that there is none.
--
-- THE ENGINES. engines/economics/fdp/* and engines/economics/projectControls.js
-- as repaired in EC6-0 and EC6-1 (engines #179 and #180): scenario economics on
-- the concept's own three capex fields with every silent default refused by
-- name, reserves totalled per fluid, a real critical path method with float and
-- refusals, calendar-day spans that do not move with a time zone, one risk
-- banding scale with an Unscored band, an internal rate of return reported only
-- when it is a verified root inside the band the engine searches, and earned
-- value with a planned value time-phased to a stated as-of date.
-- ============================================================================

insert into public.academy_apps (slug, name, module, path_order, status, prereq_slug)
values ('fdp', 'Field Development Planning', 'economics', 58, 'coming_soon', null)
on conflict (slug) do nothing;

insert into public.academy_capstones
    (app_slug, tier, cert_tier, dataset, title, prompt, fields)
